	@Override public URI getAbsoluteFileLocation() {
		if (memoizedAbsoluteFileLocation == NOT_CALCULATED_MARKER) {
			memoizedAbsoluteFileLocation = getAbsoluteFileLocation((JCCompilationUnit) top().get());
